using SimplePZMapmaker.Web.Services;
using System.Text;
using System.Text.Json;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
using System.IO.Compression;

public static class ModAssetTests
{
 public static IEnumerable<(string Name,Action Run)> Cases()
 {
  yield return("binary tdef preserves physical flags and empty slots",()=>{using var data=Definition();var tiles=TileDefinitionReader.Read(data);Check(tiles.Count==2&&tiles[0].Id=="modfixture_0"&&tiles[0].Properties.ContainsKey("solidfloor")&&tiles[1].Properties.Count==0,"tdef metadata lost");});
  yield return("binary tdef rejects truncated version counts and oversized strings",()=>{foreach(var bytes in new[]{Array.Empty<byte>(),"tdef"u8.ToArray(),"tdef\x02\0\0\0"u8.ToArray(),"tdef\x01\0\0\0\xff\xff\xff\x7f"u8.ToArray()})Reject(()=>TileDefinitionReader.Read(new MemoryStream(bytes)));using var valid=Definition();Reject(()=>TileDefinitionReader.Read(new MemoryStream(valid.ToArray()[..^1])));});
  yield return("mod registry selects compatible version layer and dependency order",()=>WithFixture(root=>{Info(root,"base",null);Info(root,"child","base");Info(root,"child/42.0","base","42.0.0");Info(root,"child/42.20","base","42.20.0");var found=ModRegistry.Discover([root],"42.0.0");Check(found.Mods["child"].InfoPath.Contains("42.0"),"Wrong version selected");var order=ModRegistry.Order(found.Mods,["child"]);Check(order.Select(m=>m.Id).SequenceEqual(new[]{"base","child"}),"Dependency order wrong");Reject(()=>ModRegistry.Order(found.Mods,["missing"]));}));
  yield return("mod registry rejects unsafe roots and dependency cycles",()=>WithFixture(root=>{Info(root,"a","b");Info(root,"b","a");var found=ModRegistry.Discover([root],"42.0.0");Reject(()=>ModRegistry.Order(found.Mods,["a"]));Reject(()=>ModRegistry.SafePath("C:\\never-read"));}));
  yield return("saved mod tile provenance rejects replacement provider and exports requirement",()=>WithFixture(root=>{
   if(!Directory.Exists(@"./game-installation\media")){Console.WriteLine("SKIP installed-game tile provenance fixture: game absent");return;}
   foreach(var id in new[]{"one","two"}){Info(root,id,null);var media=Path.Combine(root,id,"media");Directory.CreateDirectory(media);File.AppendAllText(Path.Combine(root,id,"mod.info"),"tiledef=fixture 900\n");using var file=File.Create(Path.Combine(media,"fixture.tiles"));using var w=new BinaryWriter(file,Encoding.Latin1);w.Write("tdef"u8);w.Write(1);w.Write(1);Line(w,"floors_interior_tilesandwood_01");Line(w,"fixture.png");w.Write(9);w.Write(1);w.Write(900);w.Write(9);for(var i=0;i<9;i++){w.Write(1);Line(w,"solidfloor");Line(w,"");}}
   var assets=new GameAssetCatalog(root,@"./game-installation");assets.DiscoverMods([root],"42.0.0");assets.ActivateMods(["one"]);var p=MapGenerator.Generate(new(){Kind="blank"});var b=new Building{X=40,Y=40};BuildingDesigner.Generate(b,1,42);b.Design!.Floors[0].FloorTile="floors_interior_tilesandwood_01_8";p.Buildings.Add(b);AssetRules.StampDependencies(p,assets);Check(p.Version==6&&p.RequiredMods.Contains("one")&&b.AssetSources["floors_interior_tilesandwood_01_8"]=="one","Mod requirements/provider not stamped");AssetRules.Project(p,assets);
   using var zip=new ZipArchive(new MemoryStream(NativeMapExporter.Export(p)));using var info=new StreamReader(zip.GetEntry(NativeMapExporter.ModId(p)+"/42/mod.info")!.Open());Check(info.ReadToEnd().Contains("require=one"),"Native mod requirement missing");Check(!zip.Entries.Any(e=>e.FullName.EndsWith(".pack")||e.FullName.EndsWith(".tiles")),"Foreign resources bundled");
   assets.ActivateMods(["two"]);Reject(()=>AssetRules.StampDependencies(b,assets));Check(b.AssetSources["floors_interior_tilesandwood_01_8"]=="one","Rejected provider change mutated provenance");
  }));
  yield return("actual Workshop tilepack previews and activation failure retains working catalog",()=>WithFixture(root=>{
   if(!Directory.Exists(ModRegistry.WorkshopRoot)||!Directory.Exists(@"./game-installation\media")){Console.WriteLine("SKIP real Workshop preview: installation absent");return;}
   var assets=new GameAssetCatalog(root,@"./game-installation");Check(assets.Ready,"Installed game assets unavailable");assets.DiscoverMods([ModRegistry.WorkshopRoot],"42.0.0");assets.ActivateMods(["Erikas_Tiles"]);var sample=assets.ActiveSources().Where(s=>s.RequiredModId=="Erikas_Tiles").ToArray();Check(sample.Any(s=>s.Root.EndsWith("common"))&&sample.Any(s=>s.Root.EndsWith("42")),"B42 common/version layers missing");
   // Actual sprite names are chosen from the mod's parsed definition rather than a guessed suffix.
   using var stream=File.OpenRead(Path.Combine(sample.Single(s=>s.Root.EndsWith("common")).Root,"media","Erikas_Tiles.tiles"));var tile=TileDefinitionReader.Read(stream).First(t=>assets.Get(t.Id).Page is not null);var loaded=assets.Get(tile.Id);Check(loaded.ModId=="Erikas_Tiles"&&loaded.Sprite is not null,"Mod provenance/image missing");var png=assets.Page(loaded.Page!);Check(png.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}),"Actual preview not PNG");Check(assets.ResolveRequirements([tile.Id]).Single().ModId=="Erikas_Tiles","Required mod missing");var count=assets.Count;
   var bad=Path.Combine(root,"broken");Directory.CreateDirectory(Path.Combine(bad,"media"));File.WriteAllText(Path.Combine(bad,"mod.info"),"id=broken\nname=Broken\ntiledef=broken 900\n");File.WriteAllBytes(Path.Combine(bad,"media","broken.tiles"),"tdef"u8.ToArray());assets.DiscoverMods([ModRegistry.WorkshopRoot,root],"42.0.0");Reject(()=>assets.ActivateMods(["Erikas_Tiles","broken"]));Check(assets.Count==count&&assets.Get(tile.Id).ModId=="Erikas_Tiles","Bad mod destroyed active catalog");assets.ActivateMods([]);Check(assets.ActiveSources().Count==1&&assets.ResolveRequirements(["floors_interior_tilesandwood_01_8"]).Count==0,"Disable did not restore vanilla");
  }));
  yield return("generated terrain requires its mod and removed explicit resource prunes stale requirement",()=>WithFixture(root=>{
   Info(root,"terrain",null);var media=Path.Combine(root,"terrain","media");Directory.CreateDirectory(media);File.AppendAllText(Path.Combine(root,"terrain","mod.info"),"tiledef=terrain 901\n");using(var w=new BinaryWriter(File.Create(Path.Combine(media,"terrain.tiles")),Encoding.UTF8)){w.Write("tdef"u8);w.Write(1);w.Write(1);Line(w,"blends_natural_01");Line(w,"fixture.png");w.Write(65);w.Write(1);w.Write(901);w.Write(65);for(var i=0;i<65;i++){w.Write(1);Line(w,"solidfloor");Line(w,"");}}
   var assets=new GameAssetCatalog(root,@"./game-installation");assets.DiscoverMods([root],"42.0.0");assets.ActivateMods(["terrain"]);var p=MapGenerator.Generate(new(){Kind="blank"});AssetRules.Project(p,assets);Check(p.RequiredMods.SequenceEqual(new[]{"terrain"})&&p.AssetSources["blends_natural_01_32"]=="terrain","Procedural ground dependency lost");
   if(!Directory.Exists(@"./game-installation\media"))return;
   var q=MapGenerator.Generate(new(){Kind="blank"});Array.Fill(q.Terrain,Terrain.Road);q.SurfaceTiles[10]="blends_natural_01_32";q.Terrain[10]=Terrain.Grass;AssetRules.Project(q,assets);Check(q.RequiredMods.Contains("terrain"),"Explicit dependency absent");q.SurfaceTiles.Clear();q.Terrain[10]=Terrain.Road;assets.ActivateMods([]);AssetRules.Project(q,assets);Check(q.RequiredMods.Count==0&&!q.AssetSources.ContainsKey("blends_natural_01_32"),"Unused requirement retained");using var zip=new ZipArchive(new MemoryStream(NativeMapExporter.Export(q)));using var reader=new StreamReader(zip.GetEntry(NativeMapExporter.ModId(q)+"/42/mod.info")!.Open());Check(!reader.ReadToEnd().Contains("require="),"Native export still requires removed mod");
  }));
 }
 private static MemoryStream Definition(){var data=new MemoryStream();using(var w=new BinaryWriter(data,Encoding.Latin1,true)){w.Write("tdef"u8);w.Write(1);w.Write(1);Line(w,"modfixture");Line(w,"fixture.png");w.Write(2);w.Write(1);w.Write(1991);w.Write(1);w.Write(1);Line(w,"solidfloor");Line(w,"");}data.Position=0;return data;}
 private static void Line(BinaryWriter w,string value){w.Write(Encoding.Latin1.GetBytes(value));w.Write((byte)10);}
 private static void Info(string root,string sub,string? require,string? version=null){var dir=Path.Combine(root,sub);Directory.CreateDirectory(dir);var id=sub.Split('/')[0];File.WriteAllText(Path.Combine(dir,"mod.info"),$"id={id}\nname={id}\n"+(require is null?"":"require="+require+"\n")+(version is null?"":"versionMin="+version+"\n"));}
 private static void WithFixture(Action<string> action){var workspace=Environment.GetEnvironmentVariable("PZMAP_WORKSPACE")??@"./SimplePZMapmaker";var root=Path.Combine(workspace,"work","mod-tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{action(root);}finally{var checkedRoot=Path.GetFullPath(root);var prefix=Path.GetFullPath(Path.Combine(workspace,"work","mod-tests"))+Path.DirectorySeparatorChar;if(!checkedRoot.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new Exception("Unsafe fixture cleanup");Directory.Delete(checkedRoot,true);}}
 private static void Check(bool value,string error){if(!value)throw new Exception(error);}
 private static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Invalid mod data accepted");}
}
